 if(ui.mode==='staff'&&['team','events'].includes(ui.view))ui.view='overview';
 if(ui.mode==='manager'&&ui.view==='availability')ui.view='team';
 if(ui.view==='schedule')ensureCalendar();
 const isMgr=ui.mode==='manager';
 const viewFns={overview:()=>isMgr?overviewMgr():overviewStaff(),schedule:()=>scheduleView(),events:()=>isMgr?eventsView():overviewStaff(),cash:()=>cashView(),requests:()=>requestsView(),team:()=>isMgr?teamView():availabilityView(),availability:()=>availabilityView(),profile:()=>isMgr?settingsView():profileView()};
