if(f.getAttribute('id')==='payout-form'){if(ui.mode!=='manager')return;const id=String(d.get('id')),date=ui.cashDate,cl=closureFor(date);if(cl.status==='approved')return;const s=settlement(date).rows.find(x=>x.id===id);if(!s)return;const base=positiveH(d.get('base')),paidCash=positiveH(d.get('paidCash')),paidTransfer=positiveH(d.get('paidTransfer'));if(base>100000000||paidCash>100000000||paidTransfer>100000000){toast('Zkontroluj výši částek.',true);return}if(paidCash+paidTransfer>base+s.fourPct+s.tip){toast('Vyplacená částka převyšuje vyúčtování.',true);return}cl.payouts??={};cl.payouts[id]={base,paidCash,paidTransfer,by:'manager',at:Date.now()};if(cl.status==='pending')cl.status='draft';state.closures[date]=cl;event('Zapsána výplata '+s.person.name+' · '+date);persist();closeModal();render();toast('Výplata zapsána.');return}
if(f.getAttribute('id')==='closure-form'){const date=String(d.get('date'));if(!date||date!==ui.cashDate)return;const cl={...closureFor(date)};if(ui.mode==='staff'&&!state.shifts.some(s=>s.date===date&&s.employeeId===ui.person)){toast('Pro tento den nemáš přiřazenou směnu.',true);return}if(cl.status==='approved'||(cl.status==='pending'&&ui.mode!=='manager'))return;for(const k of ['opening','cash','card','tipCash','tipCard','counted','terminal','otherOut']){const num=Number(d.get(k));if(!Number.isFinite(num)||num<0||num>100000000){toast('Zkontroluj částky.',true);return}cl[k]=positiveH(num)}cl.note=String(d.get('note')||'').trim().slice(0,500);cl.varianceNote=String(d.get('varianceNote')||'').trim().slice(0,500);const intent=String(e.submitter?.value||'draft');cl.status=intent==='submit'?'pending':'draft';cl.createdBy=ui.mode==='manager'?'Manažer':getPerson(ui.person)?.name||'Obsluha';cl.submittedAt=intent==='submit'?Date.now():cl.submittedAt;const preview=settlement(date,cl);if(preview.unallocated&&intent==='submit'){toast('Nejdřív nastav rozdělení podílu a dýšek.',true);return}if(preview.expectedCash<0&&intent==='submit'){toast('Výsledná očekávaná hotovost je záporná.',true);return}state.closures[date]=cl;event('Uzávěrka '+date+' '+(intent==='submit'?'odeslána ke kontrole.':'uložena.'));persist();render();toast(intent==='submit'?'Uzávěrka odeslána manažerovi.':'Rozpracovaná uzávěrka uložena.');return}
