if(f.getAttribute('id')==='leave-form'){const date=d.get('date');if(date<dateISO(new Date())){toast('Vyber budoucí datum.',true);return}state.requests.push({id:'r'+state.nextId++,type:'leave',employeeId:ui.person,date,note:String(d.get('note')||'').slice(0,200),status:'pending',created:Date.now()});event('Nová žádost o volno: '+getPerson(ui.person).name+' · '+fmtShort(date));persist();closeModal();ui.view='requests';ui.filter='pending';render();toast('Žádost o volno odeslána.');return}
